// On-demand traversal only. Dependencies keep the batch flow testable without
// connecting a wallet or submitting a transaction.
export async function collectReferralCredits({ owner, readReferrals, readSub, readId, submit, checkAccount, onProgress = () => {} }) {
  const seen = new Set([owner.toLowerCase()]);
  let frontier = [owner.toLowerCase()], completed = 0;
  const candidates = [];
  try {
    // AFKing pays the direct affiliate and two uplines. Scan those three levels,
    // retaining sibling order so the contract can share its upline lookups.
    for (let depth = 0; depth < 3 && frontier.length; depth++) {
      const next = [];
      for (let start = 0; start < frontier.length; start += 4) {
        checkAccount();
        onProgress('Checking referrals…');
        const pages = await Promise.all(frontier.slice(start, start + 4).map(readReferrals));
        checkAccount();
        for (const page of pages) {
          if (!Array.isArray(page?.referees) || Number(page.total ?? page.referees.length) > page.referees.length) {
            throw Error('The full referral list could not be loaded. Try again.');
          }
          for (const row of page.referees) {
            const address = String(row.address || '').toLowerCase();
            if (!/^0x[0-9a-f]{40}$/.test(address)) throw Error('A referral account could not be read. Try again.');
            if (seen.has(address)) continue;
            seen.add(address); next.push(address); candidates.push(address);
          }
        }
      }
      frontier = next;
    }
    const ids = [];
    for (let start = 0; start < candidates.length; start += 8) {
      checkAccount();
      onProgress(`Checking credit ${Math.min(start + 8, candidates.length)}/${candidates.length}…`);
      const wave = await Promise.all(candidates.slice(start, start + 8).map(async address => {
        const sub = await readSub(address);
        if (sub == null) throw Error('AFKing credit could not be checked. Try again.');
        if (!(sub.member ?? sub[0]) || BigInt(sub.owedAffiliateBase ?? sub[12] ?? 0) === 0n) return null;
        const id = await readId(address);
        if (!Number.isInteger(id) || id <= 0 || id > 0xffffffff) throw Error('A referral wallet ID could not be read. Try again.');
        return id;
      }));
      ids.push(...wave.filter(id => id != null));
    }
    const unique = [...new Set(ids)];
    // Bound transaction size; large networks continue in confirmed batches.
    for (let start = 0; start < unique.length; start += 32) {
      checkAccount();
      onProgress(`Collecting ${Math.floor(start / 32) + 1}/${Math.ceil(unique.length / 32)}…`);
      const batch = unique.slice(start, start + 32);
      await submit(batch);
      completed += batch.length;
    }
    return { completed };
  } catch (cause) {
    const error = new Error(cause?.message || 'Could not collect AFKing credit.', { cause });
    error.completed = completed;
    throw error;
  }
}
